// IEEE OUI registry: first three bytes of a MAC address -> the org the
// block was assigned to. Only useful for *static* (identity) addresses;
// phones mostly use rotating private addresses, whose first bytes are
// meaningless. The dataset is generated by tools/gen-oui.mjs from the
// IEEE's published registry file and committed so the app works offline
// (it is ~1 MB of plain JSON, which Hermes loads fine as a bundle module).

const DATA: Record<string, string> = require('./oui-data.json');

export function lookupOui(prefix3: number[]): string | undefined {
  if (prefix3.length < 3) {
    return undefined;
  }
  const key = prefix3.map(b => b.toString(16).padStart(2, '0')).join('').toUpperCase();
  return DATA[key];
}

export function ouiCount(): number {
  return Object.keys(DATA).length;
}
